const raw = $input.first().json.body || $input.first().json;
const stream = String(raw.stream || (raw.rule ? 'wazuh' : 'litellm')).toLowerCase();
const nowTime = new Date().toISOString().slice(11, 19) + 'Z';

if (stream === 'wazuh' || raw.rule) {
  const level = Number(raw.rule?.level ?? raw.level ?? 0);
  const ruleId = raw.rule?.id || raw.ruleId || 'WAZUH-EVT';
  const desc = raw.rule?.description || raw.detail || 'Wazuh SIEM/FIM/UEBA alert';
  const agentName = raw.agent?.name || raw.agentName || 'empire-prod-b';
  const status = level >= 10 ? 'needs_review' : 'compliant';

  return [{
    json: {
      tenantId: raw.tenantId || 'eds-360',
      scope: 'department',
      key: 'socaas',
      sourceLabel: 'p2-wazuh',
      kpis: [
        { label: 'SOC Watch Coverage', value: '24/7/365', sub: `Wazuh @ ${nowTime}`, accent: 'text-emerald-300' },
        { label: 'Latest Alert Level', value: `Lvl ${level}`, sub: `Rule ${ruleId} on ${agentName}`, accent: level >= 10 ? 'text-amber-300' : 'text-cyan-300' },
        { label: 'SIEM & UEBA Stack', value: 'Active', sub: 'SI.L2-3.14.1 / AU.L2-3.3.1', accent: 'text-emerald-300' },
        { label: 'HITL Escalation', value: level >= 10 ? 'Staged' : 'Standby', sub: 'SHA-256 attested gate', accent: 'text-indigo-300' }
      ],
      items: [
        {
          ref: `WAZUH-${ruleId}`,
          owner: 'SOC Watch & Wazuh SIEM',
          detail: `${desc} (${agentName}) â€” SI.L2-3.14.1 / AU.L2-3.3.1`,
          status
        }
      ]
    }
  }];
}

const gwStatus = raw.gatewayStatus || 'Healthy';
const vllmStatus = raw.vllmStatus || 'Online';
const bgeStatus = raw.bgeStatus || 'Ready';
const rlsStatus = raw.rlsStatus || 'Enforced';

return [{
  json: {
    tenantId: raw.tenantId || 'eds-360',
    scope: 'it',
    key: 'devops',
    sourceLabel: 'p2-litellm-vllm',
    kpis: [
      { label: 'LiteLLM Gateway', value: gwStatus, sub: 'Proxy :4000/v1 + Redis', accent: 'text-emerald-300' },
      { label: 'vLLM / APC Engine', value: vllmStatus, sub: `Checked ${nowTime}`, accent: 'text-cyan-300' },
      { label: 'Embeddings (bge-m3)', value: bgeStatus, sub: 'Local RAG & search', accent: 'text-indigo-300' },
      { label: 'Safety & RLS Wall', value: rlsStatus, sub: 'LLM Guard + Postgres RLS', accent: 'text-emerald-300' }
    ],
    items: [
      {
        ref: raw.ref || 'LLM-GW-TELEMETRY',
        owner: 'Prod AI & Infra',
        detail: raw.detail || `LiteLLM=${gwStatus}, vLLM=${vllmStatus}, bge-m3=${bgeStatus}, RLS=${rlsStatus} (AC.L2-3.1.1 / AU.L2-3.3.1)`,
        status: raw.itemStatus || 'compliant'
      }
    ]
  }
}];

const sites = [
  { id: 'main', url: 'https://emergingdefensesolutions.com', label: 'Main Site (EDS)', group: 'executive' },
  { id: 'defense', url: 'https://defense.eds-360.com', label: 'Defense Portal', group: 'executive' },
  { id: 'cyber', url: 'https://cyber.eds-360.com', label: 'Cyber / SOCaaS', group: 'socaas' },
  { id: 'nps', url: 'https://nps.eds-360.com', label: 'NPS Portal', group: 'operations' },
  { id: 'hive', url: 'https://hive.eds-360.com', label: 'HIVE Platform', group: 'operations' },
  { id: 'meu', url: 'https://meu.eds-360.com', label: 'MEU Portal', group: 'operations' },
  { id: 'cyberdojosensei', url: 'https://cyberdojosensei.eds-360.com', label: 'Cyber Dojo Sensei', group: 'marketing' },
  { id: 'shauntzemorman', url: 'https://shauntzemorman.info', label: 'Shaun Tze Morman', group: 'executive' },
  { id: 'hive-align', url: 'https://hive-align.eds-360.com', label: 'HIVE-Align', group: 'operations' }
];

const results = [];
for (const s of sites) {
  const started = Date.now();
  let ok = false;
  let statusCode = 0;
  let errMsg = '';
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 5000);
    const res = await fetch(s.url, { method: 'GET', redirect: 'follow', signal: ctrl.signal });
    clearTimeout(timer);
    statusCode = res.status;
    ok = (res.status >= 200 && res.status < 400) || (s.id === 'hive' && res.status === 403);
  } catch (e) {
    errMsg = e && e.message ? e.message : 'unreachable';
  }
  results.push({
    ...s,
    ok,
    statusCode,
    latencyMs: Date.now() - started,
    errMsg
  });
}

const upCount = results.filter(r => r.ok).length;
const downSites = results.filter(r => !r.ok);
const avgMs = Math.round(results.reduce((acc, r) => acc + r.latencyMs, 0) / Math.max(1, results.length));
const nowTime = new Date().toISOString().slice(11, 19) + 'Z';

const items = results.map(r => {
  const stateText = r.ok
    ? (r.statusCode === 403 ? 'HTTP 403 (WAF/Auth Protected)' : `HTTP ${r.statusCode}`)
    : `DOWN (${r.errMsg || r.statusCode})`;
  return {
    ref: `WEB-${r.id.toUpperCase()}`,
    owner: 'Web & Edge Ops',
    detail: `${r.label} (${r.url}) -> ${stateText} [${r.latencyMs}ms] (SI.L2-3.14.1)`,
    status: r.ok ? 'compliant' : 'needs_review'
  };
});

return [{
  json: {
    tenantId: 'eds-360',
    scope: 'department',
    key: 'executive',
    sourceLabel: 'n8n-all-9-sites',
    kpis: [
      { label: 'Web Properties Up', value: `${upCount} / ${results.length}`, sub: `Checked ${nowTime}`, accent: downSites.length === 0 ? 'text-emerald-300' : 'text-amber-300' },
      { label: 'Avg Response', value: `${avgMs} ms`, sub: 'Across all 9 domains', accent: 'text-cyan-300' },
      { label: 'Degraded / Down', value: `${downSites.length}`, sub: downSites.length ? downSites.map(d => d.id).join(', ') : 'All properties healthy', accent: downSites.length ? 'text-rose-300' : 'text-emerald-300' },
      { label: 'Edge & Telemetry', value: 'Monitored', sub: 'SI.L2-3.14.1 / AU.L2-3.3.1', accent: 'text-indigo-300' }
    ],
    items
  }
}];
